/** Joins PUBLIC_URL with a public-folder path (handles optional subpath deploys). */
export function publicAssetUrl(path: string): string {
  const base = (process.env.PUBLIC_URL ?? '').replace(/\/$/, '');
  const normalized = path.startsWith('/') ? path : `/${path}`;
  return `${base}${normalized}`;
}

/** Public URL to the official Sustainow Carbon Intelligence logo (PNG). */
export const BRAND_LOGO_SRC = publicAssetUrl('/sustainow-ci-logo.png');
