/** Resolve pre-login brand scene for the active color mode. */
export function brandPreloginSceneSrc(mode: 'light' | 'dark' = 'light'): string {
  return mode === 'dark' ? BRAND_PRELOGIN_SCENE_SRC : BRAND_PRELOGIN_SCENE_LIGHT_SRC;
}
